/* index column (value = port) vs value column (config bool array). */
static int
ports_pbmp_col(const struct ies_auto_mibs_entry *e)
{
    return (strcmp(e->uri_index, "portIndex") == 0) ? IES_COL_ROW_INDEX
                                                    : IES_COL_PBMP_VALUE;
}

/* A generic config index-table column: oid_index==1, the config is an object
 * array addressed per field as "<uri><row-1>/<column>" (column = uri_index).
 * Fixed-size config arrays (e.g. syslog): register up to MAX_TABLE_ROWS and let
 * the handler return noSuchInstance past the array's end. Status-layer device_io
 * tables use the product max IO counts instead (see index_table_rows). */
#define REUSE_MAX_TABLE_ROWS 16

static int
is_index_table(const struct ies_auto_mibs_entry *e)
{
    /* turboring ring is a NAMED-KEY group ({ring1,ring2}), not an array
     * index-table — see is_turboring_ring(). Excluding it here keeps its
     * UNSUPPORTED columns (e.g. "interface", the deferred REDUNDANT_PORT) out of
     * the table entirely. Otherwise they fall through to the index-table branch
     * and emit REUSE_MAX_TABLE_ROWS rows whose path is built as
     * "<uri><row-1>/<col>" -> "turboringv20/interface", which can never resolve:
     * 16 permanently valueless OIDs that a GETNEXT has to step over one by one. */
    if (strcmp(e->uri, "config/turboringv2/ring/") == 0 ||
        strcmp(e->uri, "stat/turboringv2/ring/") == 0)
    {
        return 0;
    }
    return e->oid_index == 1 &&
           strcmp(e->uri_index, "0") != 0 &&
           !is_ports_pbmp(e) &&
           strncmp(e->uri, "stat/", 5) != 0;
}

/* Row count for one index-table column. device_io status arrays are sized by
 * LibSystem max counts (same length plugin_moxa_io::get_status builds); other
 * index tables keep REUSE_MAX_TABLE_ROWS. Returns 0 to skip registration. */
static uint32_t
index_table_rows(const char *uri)
{
    uint32_t n = 0;

    /* plugin_moxa_snmp config_snmp_trap.rs: host.maxItems = 2 */
    if (strcmp(uri, "snmpTrap/host/") == 0)
    {
        return 2;
    }
    if (strcmp(uri, "io/power/system/") == 0)
    {
        if (LibSystem_GetMaxNumOfSystemPower(&n) != 0 || n == 0 || n > 256)
        {
            return 0;
        }
        return n;
    }
    if (strcmp(uri, "io/power/poe/") == 0)
    {
        if (LibSystem_GetMaxNumOfExtPsePower(&n) != 0 || n > 256)
        {
            return 0;
        }
        return n;   /* 0 = no PoE power rails; skip */
    }
    if (strcmp(uri, "io/di/") == 0)
    {
        if (LibSystem_GetMaxNumOfDi(&n) != 0 || n == 0 || n > 256)
        {
            return 0;
        }
        return n;
    }
    if (strcmp(uri, "io/relay/") == 0)
    {
        if (LibSystem_GetMaxNumOfDo(&n) != 0 || n == 0 || n > 256)
        {
            return 0;
        }
        return n;
    }
    return REUSE_MAX_TABLE_ROWS;
}

/* turboring ring table (config AND status): named-key data ({ring1,ring2}), path
 * "<mod_uri>/ring<N>/<column>" (N = ring number, 1-based). 2 rings, fixed. The
 * setup fn sets mod_uri="turboringv2" for both, so the stored uri drops the
 * "config/"/"stat/" prefix; is_status (from the "stat/" prefix, mapping below)
 * then routes the status columns to the status layer. index column -> row number;
 * value columns -> IES_COL_TR2RING_VALUE. config "interface" (REDUNDANT_PORT) is
 * deferred (skipped). */
#define TR2_RING_NUM 2

static int
is_turboring_ring(const struct ies_auto_mibs_entry *e)
{
    if (strcmp(e->uri, "config/turboringv2/ring/") == 0)
    {
        return strcmp(e->uri_index, "index") == 0 ||
               strcmp(e->uri_index, "enable") == 0 ||
               strcmp(e->uri_index, "master") == 0;
    }
    /* status ring columns: {ring1,ring2} named-key, DUT-verified addressable as
     * /api/v1/status/turboringv2/ring<N>. designatedMaster is a MacAddress. */
    if (strcmp(e->uri, "stat/turboringv2/ring/") == 0)
    {
        return strcmp(e->uri_index, "index") == 0 ||
               strcmp(e->uri_index, "masterStatus") == 0 ||
               strcmp(e->uri_index, "designatedMaster") == 0 ||
               strcmp(e->uri_index, "firstPortStatus") == 0 ||
               strcmp(e->uri_index, "secondPortStatus") == 0 ||
               strcmp(e->uri_index, "brokenStatus") == 0;
    }
    return 0;
}

/* Physical port count = length of the portsPbmp config array. 0 disables table
 * expansion (falls back to skipping, as before). */
static uint32_t
system_port_num(void)
{
    uint32_t n = 0;
    if (LibSystem_GetMaxPortNumInSystem(&n) != 0 || n == 0 || n > 256)
    {
        return 0;
    }
    return n;
}

/* Fill one row: instance OID = e->oid_list + `suffix` (.0 for a scalar, or the
 * port number for a table column). Returns 0 on success. */
static int
emit_row(struct ies_map_entry *row, const struct ies_auto_mibs_entry *e,
         moxa_oid suffix, const char *uri, const char *uri_index, int table_col)
{
    moxa_oid *o;
    int j;

    o = (moxa_oid *) malloc((e->oid_len + 1) * sizeof(moxa_oid));
    if (o == NULL)
    {
        return -1;
    }
    for (j = 0; j < e->oid_len; j++)
    {
        o[j] = (moxa_oid) e->oid_list[j];
    }
    o[e->oid_len] = suffix;

    row->oid       = o;
    row->oid_len   = (size_t) (e->oid_len + 1);
    row->uri       = uri;         /* static storage; lives for program */
    row->uri_index = uri_index;   /* "" for scalar/pbmp; column name for index-table */
    row->val_type  = e->val_type; /* SNMP_DATA_TYPE_* == ASN tag */
    row->mode      = e->mode;
    row->table_col = table_col;
    /* Served from the status layer if the URI had a "stat/" prefix (turboring)
     * or the setup marked it IES_FLAG_SNMP_URI_STATUS (device_io). */
    row->is_status = (strncmp(e->uri, "stat/", 5) == 0 ||
                      IES_FLAG_BITS_CHK(IES_FLAG_SNMP_URI_STATUS, e->flags)) ? 1 : 0;
    /* Port interface index: 0-based in the config layer, 1-based in SNMP. The
     * flags bit array itself is not carried over — each flag whose semantics the
     * framework implements is extracted into its own field, like is_status. */
    row->is_iface = IES_FLAG_BITS_CHK(IES_FLAG_SNMP_URI_INTERFACE, e->flags) ? 1 : 0;
    return 0;
}

static void
build_reuse_table(void)
{
    size_t   nsrc = sizeof(g_reuse_srcs) / sizeof(g_reuse_srcs[0]);
    size_t   s, i, n, k;
