                 * other value columns -> "<uri><row-1>/<column>". */
                int      col;
                uint32_t rows = index_table_rows(e->uri);
                uint32_t r;

                if (strcmp(e->uri_index, "index") == 0)
                {
                    col = IES_COL_IDXTBL_INDEX;
                }
                else if (strcmp(e->uri_index, "rowStatus") == 0)
                {
                    col = IES_COL_ROWSTATUS;
                }
                else
                {
                    col = IES_COL_IDXTBL_VALUE;
                }
                for (r = 1; r <= rows; r++)
                {
                    if (emit_row(&s_table[k], e, (moxa_oid) r, uri, e->uri_index, col) == 0)
                    {
                        k++;
                    }
                }
            }
            else /* is_tr2_ring */
            {
                /* index column -> ring number; enable/master -> config value
                 * at "<uri>/ring<row>/<column>". */
                int      col = (strcmp(e->uri_index, "index") == 0)
                                   ? IES_COL_ROW_INDEX
                                   : IES_COL_TR2RING_VALUE;
                uint32_t r;

                for (r = 1; r <= TR2_RING_NUM; r++)
                {
                    if (emit_row(&s_table[k], e, (moxa_oid) r, uri, e->uri_index, col) == 0)
                    {
                        k++;
                    }
                }
            }
        }
    }
    s_len = k;
}

const struct ies_map_entry *
ies_map_reuse_table(size_t *len)
{
    build_reuse_table();
    if (len != NULL)
    {
        *len = s_len;
    }
    return s_table;
}

