#ifndef _IES_MIBs_HANDLE_SET_REDUNDANT_PORT_C_
#define _IES_MIBs_HANDLE_SET_REDUNDANT_PORT_C_

#define   ISS_MOXA_MAX_REDUNDANT_PORT      (2)
#include "libmoxa_system/lib_moxa_system_l2_spec_def.h"
typedef enum {
    ISS_MOXA_REDUNDANT_PORT_PRIMARY   = 0,
    ISS_MOXA_REDUNDANT_PORT_SECONDARY = 1,
} iss_moxa_redundant_port_t;



ies_handle_t
util_redundant_port_get_uri_path
(
    struct ies_auto_mibs_entry    *entry,
    iss_moxa_redundant_port_t      port,
    oid                            req_oid_idx,
    char                          *uri_path,
    int                            uri_path_len
)
{
#if !defined(MOXA_DUAL_HOMING_HIDE_UI)
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "mxdualdb/dualhomingConfigPriSecPort") ) 
    {
        if ( ISS_MOXA_REDUNDANT_PORT_PRIMARY == port )
        {
            snprintf(uri_path, uri_path_len, IES_URI_CONFIG_PATH("/mxDualHoming/dualHomingTable/%d/sessionprimaryPort"), 0);
        }
        else
        {
            snprintf(uri_path, uri_path_len, IES_URI_CONFIG_PATH("/mxDualHoming/dualHomingTable/%d/sessionsecondaryPort"), 0);
        }
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "mxdualdb/dualhomingConfigTable/") )
    {
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "dualhomingConfigTableEntryPriSecPort") )
        {

            if ( ISS_MOXA_REDUNDANT_PORT_PRIMARY == port )
            {
                snprintf(uri_path, uri_path_len, IES_URI_CONFIG_PATH("/mxDualHoming/dualHomingTable/%d/sessionprimaryPort"), req_oid_idx-1);
            }
            else
            {
                snprintf(uri_path, uri_path_len, IES_URI_CONFIG_PATH("/mxDualHoming/dualHomingTable/%d/sessionsecondaryPort"), req_oid_idx-1);
            }

        }
    }
    else
#endif
#if !defined(MOXA_TURBO_CHAIN_HIDE_UI)
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "mxtcdb/turboChainConfigInterface") ) 
    {
        if ( ISS_MOXA_REDUNDANT_PORT_PRIMARY == port )
        {
            snprintf(uri_path, uri_path_len, IES_URI_CONFIG_PATH("/%s/primaryInterface/"), entry->mod_uri);
        }
        else
        {
            snprintf(uri_path, uri_path_len, IES_URI_CONFIG_PATH("/%s/secondaryInterface/"), entry->mod_uri);
        }
    }
    else
#endif
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "config/turboringv2/ring/") ) 
    {
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "interface") ) 
        {
            if ( ISS_MOXA_REDUNDANT_PORT_PRIMARY == port )
            {
                snprintf(uri_path, uri_path_len, 
                    IES_URI_CONFIG_PATH("/turboringv2/ring%d/firstPort"), req_oid_idx ); 
            }
            else
            {
                snprintf(uri_path, uri_path_len, 
                    IES_URI_CONFIG_PATH("/turboringv2/ring%d/secondPort"), req_oid_idx ); 
            }
        }
    }
    else 
    {
        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
        return IES_ERR;
    }
    return IES_NOERR;
}

/*-------------------------------------------------------------------+
 * Function           : ies_auto_mibs_handle_set_redundant_port
 *
 * Description        :


+-------------------------------------------------------------------*/
ies_handle_t 
ies_auto_mibs_handle_set_redundant_port
(
    netsnmp_agent_request_info     *reqinfo,
    netsnmp_request_info           *request,
    struct ies_auto_mibs_entry     *entry,
    char                           *val_string
)
{
    ies_handle_t                    ret                   = IES_ERR;
    char                            uri_path[IES_MAX_URI] = {0x0};
    struct LibFrameworkUri_Handle  *uri_handle            = NULL;
    JSON_Value                     *json_val              = NULL;
    JSON_Object                    *json_obj              = NULL;
    JSON_Value                     *json_val_ret          = NULL;
    char                           *json_val_ret_string   = NULL;
    char                            oct_char[2]           = {0x0};
    int                             i;
    oid                            *req_oid;
    int                             req_oid_len;
    oid                             req_oid_idx = 0;
    int                             oid_data_port;
    int32_t                         DH_MAX_SESSIONS = 0;
    struct uriIface_entry           interface[ISS_MOXA_MAX_REDUNDANT_PORT] = {0x0};


    req_oid     = (oid *)request->requestvb->name;
    req_oid_len = request->requestvb->name_length;

    memcpy(oct_char, request->requestvb->val.string, 2);
    LibSystem_GetL2DhMaxSession(&DH_MAX_SESSIONS);

    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "config/turboringv2/ring/") ) 
    {
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "interface") ) 
        {
            req_oid_idx = req_oid[req_oid_len - 1];
            if ( req_oid_idx >= 1 && req_oid_idx <= 2 ) 
            {
                ;
            }
            else 
            {
                LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
                return IES_ERR;
            }
        }
    }

    uri_handle = LibFrameworkUri_CreateHandle(flask_server_ip, 80);
    if ( NULL == uri_handle )
    {

        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
        goto out;
    }

#if !defined(MOXA_DUAL_HOMING_HIDE_UI)
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "mxdualdb/dualhomingConfigTable/") )
    {
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "dualhomingConfigTableEntryPriSecPort") )
        {
            req_oid_idx = req_oid[req_oid_len - 1];
            if ( req_oid_idx >= 1 && req_oid_idx <= DH_MAX_SESSIONS)
            {
                ;
            }
            else
            {
                LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
                return IES_ERR;
            }
        }
    }
#endif

    uri_handle = LibFrameworkUri_CreateHandle(flask_server_ip, 80);
    if ( NULL == uri_handle ) 
    {

        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
        goto out;
    }

    for ( i = 0; i < ISS_MOXA_MAX_REDUNDANT_PORT; i++ ) 
    {
        oid_data_port = oct_char[i];
        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "%s line %d index = %d oid_data_port = %d\n", __func__, __LINE__, i, oid_data_port);
        if ( IES_NOERR != utilURI_get_interface_entry_from_port(oid_data_port, &interface[i]) )
        {
            LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
            goto out;
        }
        if ( IES_NOERR != util_redundant_port_get_uri_path( 
                entry, i, req_oid_idx, uri_path, sizeof(uri_path)) )
        {
            LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
            goto out;
        }
        if ( 0 != LibFrameworkUri_GetUri(uri_handle, uri_path, security_token, &json_val) ) 
        {

            LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
            goto out;
        }
        json_obj = json_value_get_object(json_val);
        if( NULL == json_obj ) 
        {

            LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
            goto out;
        }

        if ( JSONSuccess != json_object_dotset_number(json_obj, "iftype", interface[i].iftype) )
        {
            LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
            goto out;
        }

        if ( JSONSuccess != json_object_dotset_number(json_obj, "index", interface[i].index) )
        {
            LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
            goto out;
        }

        if ( 0 != LibFrameworkUri_PatchUri(uri_handle, 
                uri_path, security_token, json_val, &json_val_ret) ) 
        {

            LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d !!\n", __func__, __LINE__);
            json_val_ret_string = json_serialize_to_string(json_val_ret);
            if ( NULL != json_val_ret_string ) 
            {
                LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "%s ret_string =  '%s'\n", 
                    __func__, json_val_ret_string );
                json_free_serialized_string(json_val_ret_string);
            }
            ret = IES_ERR;
            goto out;
        }
        json_value_free(json_val);
        json_val = NULL;
    }

    ret = IES_NOERR;
out:

    if (NULL != json_val)
    {
        json_value_free(json_val);
        json_val = NULL;
    }

    if ( NULL != json_val_ret ) 
    {
        json_value_free(json_val_ret);
        json_val_ret = NULL;
    }

    if ( NULL != uri_handle ) 
    {
        LibFrameworkUri_ReleaseHandle(uri_handle);
    }

    LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "%s line %d %s\n", __func__, __LINE__, 
        ( IES_NOERR == ret) ? "IES_NOERR" : "IES_ERR" );

    return ret;
}

#endif //_IES_MIBs_HANDLE_SET_REDUNDANT_PORT_C_

