ies_handle_t 
utilURI_set_interface_entry_to_json_obj
(
    JSON_Object                 *json_obj,
    char                        *uri_name,
    struct uriIface_entry       *uri_interface_entry
)
{

    ies_handle_t                 ret                = IES_ERR;
    JSON_Value                  *json_val_interface = NULL;
    JSON_Object                 *json_obj_interface = NULL;

    json_val_interface = json_value_init_object();
    if ( NULL == json_val_interface ) 
    {

        LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
        goto out;
    }

    json_obj_interface = json_value_get_object(json_val_interface);
    if ( NULL == json_obj_interface ) 
    {

         LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
         goto out;
    }

    if ( JSONSuccess != json_object_dotset_number(json_obj_interface, "iftype", uri_interface_entry->iftype) )
    {
         LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
        goto out;
    }

    if ( JSONSuccess != json_object_dotset_number(json_obj_interface, "index", uri_interface_entry->index) )
    {
         LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
         goto out;
    }

    if ( JSONSuccess != json_object_dotset_value(json_obj, uri_name, json_val_interface) )
    {
         LibUtil_DbgTrace(kDbgFlgIssUriSNMP, "Error in %s line %d\n", __func__, __LINE__);
         goto out;
    }

    ret = IES_NOERR;
out:

    return ret;
}



