/*
 * Copyright (C) MOXA Inc. All rights reserved.
 *
 * This software is distributed under the terms of the
 * MOXA License.  See the file COPYING-MOXA for details.
 */
#ifndef _IES_AUTO_MIBS_FLAGS_net_stdethdb_c
#define _IES_AUTO_MIBS_FLAGS_net_stdethdb_c



ies_handle_t 
ies_auto_mibs_setup_entry_flags_net_stdethdb
(
    struct ies_auto_mibs_entry *entry
)
{


    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "stdethdb/dot3PauseTable/") ) 
    {
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "dot3PauseAdminMode") ) 
        {
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_MOD_ON_SET, entry->flags);
            snprintf(entry->mod_uri      , IES_MAX_URI,       "etherlike/portTable/");
            snprintf(entry->mod_uri_index, IES_MAX_URI_INDEX, "dot3Pause");
        }
    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "stdethdb/dot3ControlTable/") ) 
    {
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "dot3ControlFunctionsSupported") ) 
        {
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_BIT_VALUE, entry->flags);
        }
    }

    return IES_NOERR;
}



#endif //_IES_AUTO_MIBS_FLAGS_net_stdethdb_c

