#ifndef _IES_AUTO_MIBS_FLAGS_net_mxPortdb_c_
#define _IES_AUTO_MIBS_FLAGS_net_mxPortdb_c_



ies_handle_t 
ies_auto_mibs_setup_entry_flags_net_mxPortdb
(
    struct ies_auto_mibs_entry *entry
)
{


    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "mxportdb/portConfigTable/") ) 
    {
        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_MOD_ON_SET, entry->flags);
        snprintf(entry->mod_uri, IES_MAX_URI, "mxport/portTable/");

        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "portConfigDescription") ) 
        {
            snprintf(entry->mod_uri_index, IES_MAX_URI_INDEX, "description");
        }
        else
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "portConfigMode") ) 
        {
            snprintf(entry->mod_uri_index, IES_MAX_URI_INDEX, "autoNego");
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);
        }
        else
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "portConfigDuplex") ) 
        {
            snprintf(entry->mod_uri_index, IES_MAX_URI_INDEX, "duplex");
        }
        else
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "portConfigSpeed") ) 
        {
            snprintf(entry->mod_uri_index, IES_MAX_URI_INDEX, "speed");
        }
        else
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "portConfigMdiOrMdixCap") ) 
        {
            snprintf(entry->mod_uri_index, IES_MAX_URI_INDEX, "mdiOrMdix");
        }

    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "mxportdb/portConfigSystemLinkUpDelayEnable") ) 
    {

        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_MOD_ON_SET, entry->flags);
        snprintf(entry->mod_uri , IES_MAX_URI, "mxport/linkUpDelayEnable");
        snprintf(entry->mod_uri_index, IES_MAX_URI_INDEX, "0");

        IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);

    }
    else
    if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri, "mxportdb/portConfigLinkUpDelayTable/") ) 
    {

        IES_FLAG_BITS_SET(IES_FLAG_SNMP_URI_MOD_ON_SET, entry->flags);
        snprintf(entry->mod_uri , IES_MAX_URI, "mxport/linkUpDelayPortTable/");

        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "portConfigLinkUpDelayEnable") ) 
        {
            snprintf(entry->mod_uri_index, IES_MAX_URI_INDEX, "portEnable");
            IES_FLAG_BITS_SET(IES_FLAG_SNMP_REPLACE_TRUTH_VALUE, entry->flags);
        }
        else
        if ( IES_NOERR == IES_SNMP_COMPARE_URI(entry->uri_index, "portConfigLinkUpDelayTimer") ) 
        {
            snprintf(entry->mod_uri_index, IES_MAX_URI_INDEX, "delayTimer");
        }
    }
    return IES_NOERR;
}



#endif //_IES_AUTO_MIBS_FLAGS_net_mxPortdb_c_

