pub fn get_config_from_path(
    plugins: &mut plugins_moxa_framework::config::Plugins,
    userinfo: &user_info::UserInfo,
    path: &str,
    full_config: &serde_json::Value,
    query: Option<&QString>,
    oversize_list_index_as_last: bool,
) -> Result<serde_json::Value, ErrorCommon> {
    let request_method = &http::Method::GET;

    let attributes: Vec<&str> = path.split('/').filter(|s| &"" != s).collect();

    // Rust: (NEW)
    let mut filtered_config;

    // Check permission for requesting specific module
    if !attributes.is_empty() {
        let plugin = plugins
            .plugin(attributes[0])
            .ok_or_else(|| ErrorCommon::new(ErrorType::InternalError, path))?;
        let plugin_module_name = plugin.get_module_name().to_owned();
        _check_permission(plugin, request_method, path, userinfo, full_config)?;

        let mut return_config = full_config;
        for attr in attributes {
            if return_config.is_array() {
                if "FILTER" == attr {
                    // Rust: query is None will introduce exception in original Python code
                    let query = query
                        .ok_or_else(|| ErrorCommon::new(ErrorType::InvalidRequestUri, path))?
                        .clone();
                    let filters: Vec<(String, String)> = query
                        .into_iter()
                        .filter(|(key, _)| key != "page" && key != "per_page")
                        .collect();

                    filtered_config = serde_json::json!([]);
                    if let Some(t) = return_config.as_array() {
                        for (config_index, config_entry) in t.iter().enumerate() {
                            if let Some(u) = filtered_config.as_array_mut() {
                                if _match_config_to_filter(config_entry, &filters) {
                                    u.push(serde_json::json!({
                                        "index": config_index,
                                        "value": config_entry.clone()
                                    }));
                                }
                            }
                        }
                    }
                    return_config = &filtered_config;
                    break;
                }

                //  Rust: Will take care of index < 0 condition
                // Python allows negative index for getting array value
                // backwards, i.e., -1 means last one, but we don't
                // support it in URI.
                let mut index = attr
                    .parse::<usize>()
                    .map_err(|_| ErrorCommon::new(ErrorType::InvalidRequestUri, path))?;

